 * create the custom post type.
 */

namespace custom_functions_plugin;

defined( 'ABSPATH' ) || exit;

class custom_post_type {

    /**
     * defines the custom post type settings.
     *
     * @since 1.0.0
     */
    public function run() {
        $labels = array(
            'name'                  => __( 'custom post type', 'custom-functions-plugin' ),
            'singular_name'         => __( 'custom post', 'custom-functions-plugin' ),
            'search_items'           => __( 'search custom posts', 'custom-functions-plugin' ),
            'all_items'              => __( 'all custom posts', 'custom-functions-plugin' ),
            'edit_item'               => __( 'edit custom post', 'custom-functions-plugin' ),
            'update_item'             => __( 'update custom post', 'custom-functions-plugin' ),
            'add_new_item'            => __( 'add new custom post', 'custom-functions-plugin' ),
            'menu_name'               => __( 'custom post type', 'custom-functions-plugin' ),
        );

        $args = array(
            'labels' => $labels,
            'public' => true,
            'menu_icon' => 'dashicons-welcome-write-blog',
            'supports' => array( 'title', 'editor', 'thumbnail', ),
        );

        register_post_type( 'custom_post_type', $args );
    }
}

function init_custom_post_type() {
    global $custom_post_type;
    $custom_post_type = new custom_post_type();
    $custom_post_type->run();
