  import io.gauge.IT;
  import io.gauge.Step;
  import org.springframework.beans.factory.annotation.Autowired;
  import org.springframework.boot.test.web.client.TestRestTemplate;
  import org.springframework.http.*;
  import java.util.Random;

  public class ApiTest {
      @Autowired
      private TestRestTemplate restTemplate;

      @Step("Invoke Rest API endpoint {endpoint} with HTTP Method {method}")
      public IT.HttpResponse invokeApi(String endpoint, HttpMethod method) {
          return invokeApi(endpoint, method, null);
      }

      @Step("Invoke Rest API endpoint {endpoint} with HTTP Method {method} and Request Payload {payload}")
      public IT.HttpResponse invokeApi(String endpoint, HttpMethod method, String payload) {
          final Random random = new Random();
          int randomPort = random.nextInt(60000) + 30000;
          URL baseUrl = TestRestTemplateUtils.cleanRootUrl restTemplate.getRestTemplate().getRootUri();
          String url = baseUrl.getProtocol() + "://" + baseUrl.getHost() + ":" + randomPort + baseUrl.getPath();

          HttpHeaders headers = new HttpHeaders();
          headers.setContentType(MediaType.APPLICATION_JSON);

          RestTemplate restTemplate = new TestRestTemplate(url, randomPort);
          String jsonPayload = payload == null ? null : payload;

          HttpEntity<String> entity = new HttpEntity<>(jsonPayload, headers);
          ResponseEntity<String> responseEntity = restTemplate.exchange(endpoint, method, entity, String.class);

          return new IT.HttpResponse(responseEntity.getStatusCode(), responseEntity.getBody());
      }
  }
