// Lade das glTF-Objekt und die Animationen
function loadGLTF(fileURL, callback) {
  const loader = new THREE.GLTFLoader();

  loader.load(fileURL, gltf => {
    gltf.scene.traverse(child => {
      if (child.type === 'skinnedMesh') {
        child.mixer.addEventListener('finished', progressBar.tick);
        child.mixer.addEventListener('loop', progressBar.tick);
      }
    });

    gltf.animations.forEach((animation, index) => {
      document.getElementById('animation-list').innerHTML += `<li>${animation.tracks.length} Keyframes in Animation ${index}</li>`;
    });

    callback(gltf);
  });
}

