import javax.net.ssl.HttpsURLConnection;
import java.io.*;
import java.net.URL;

public class GetSnapshot {
    public static void main(String[] args) throws Exception {
        String apiUrl = "https://<IP-Adresse>/snapshot.cgi?camera=1";
        String cameraUsername = "<Kamera-Benutzername>";
        String cameraPassword = "<Kamera-Passwort>";

        URL obj = new URL(apiUrl);
        HttpsURLConnection con = (HttpsURLConnection) obj.openConnection();

        // set Basics to HTTPS connection
        con.setRequestMethod("GET");
        con.setRequestProperty("Username", cameraUsername);
        con.setRequestProperty("Password", cameraPassword);
        con.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");

        con.setRequestProperty("Accept-Language", "en-US,en;q=0.5");

        con.setDoOutput(true);

        int responseCode = con.getResponseCode();
        System.out.println("responseCode: " + responseCode);

        if (responseCode == HttpsURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
            String inputLine;
            StringBuffer response = new StringBuffer();
            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();
            System.out.println("response: " + response.toString());
        } else {
            System.err.println("responseCode: " + responseCode);
        }

    }
}
```

